export const CITIES: City[] = R.split(",").map((c) => {
  const p = c.lastIndexOf("|");
  const pop = +c.slice(p + 1);
  const rest = c.slice(0, p);
  const p2 = rest.lastIndexOf("|");
  const tier = +rest.slice(p2 + 1) as Tier;
  const rest2 = rest.slice(0, p2);
  const p3 = rest2.lastIndexOf("|");
  const state = rest2.slice(p3 + 1);
  const name = rest2.slice(0, p3);
  return { name, state, tier, pop };
});
